const TEAMS=['Alpha','Bravo','Charlie','Delta','Echo','Foxtrot','Golf','Hotel','India','Juliett'];
// Charlie/Foxtrot darkened from the original #ba8930/#b36332: the crest symbol
// (#fff8df on team color) fell to 2.94:1 / 4.16:1, under WCAG's 4.5:1 text
// threshold -- easy to miss on a phone in bright sun. Now 5.0:1 / 4.9:1.
const COLORS=['#ad413b','#284f85','#8a6419','#245f50','#775391','#a5591f','#46703b','#456778','#a1446b','#313d66'];
const SYMBOLS=['<path d="M16 35 30 12 44 35h-8l-6-11-6 11z"/>','<path d="m32 9-15 20h11l-3 15 18-23H31z"/>','<path d="m15 18 9 7 6-13 6 13 9-7-4 20H19z"/>','<path d="m12 36 18-25 18 25zm12-6h12l-6-9z" fill-rule="evenodd"/>','<path d="M18 13h26v6H25v5h15v6H25v6h19v6H18z"/>','<path d="m13 13 17 9 17-9-6 24-11 8-11-8zm9 13 4 4 2-3zm10 1 2 3 4-4z"/>','<g transform="translate(30 28) scale(.8) translate(-30 -28)"><path d="M14 42c0-4 7-6 16-6s16 2 16 6-7 6-16 6-16-2-16-6zm8 0c0 1.2 2.2 2 5 2s5-.8 5-2-2.2-2-5-2-5 .8-5 2z" fill-rule="evenodd"/><path d="M25 9h4v33h-4zM29 9l17 7-17 7z"/><circle cx="41" cy="33" r="3"/></g>','<path d="M17 14h7v11h12V14h7v29h-7V32H24v11h-7z"/>','<path d="m30 10 17 18-17 18-17-18zm0 10-8 8 8 8 8-8z" fill-rule="evenodd"/>','<path d="M19 12h24v7h-6v18c0 13-23 13-23-1h8c0 5 7 5 7 0V19H19z"/>'];
function crest(name){const i=TEAMS.indexOf(name);return `<svg class="crest" viewBox="0 0 60 66" aria-hidden="true"><path fill="${COLORS[i]}" d="M4 3h52v35c0 13-15 21-26 26C19 59 4 51 4 38z"/><path fill="none" stroke="#ffffff66" stroke-width="2" d="M9 8h42v29c0 10-11 17-21 22C20 54 9 47 9 37z"/><g fill="#fff8df">${SYMBOLS[i]}</g></svg>`}

// Premieskjold (samme som i Utmerkelser): brukes også i Nominert-fanen.
const AWARD_CRESTS={celebration:`<svg class="award-crest" viewBox="0 0 60 66" aria-hidden="true" focusable="false"><path fill="#2f7a63" d="M4 3h52v35c0 13-15 21-26 26C19 59 4 51 4 38z"/><path fill="none" stroke="#ffffff66" stroke-width="2" d="M9 8h42v29c0 10-11 17-21 22C20 54 9 47 9 37z"/><g fill="#fff8df"><g transform="translate(30 31) scale(.75) translate(-30 -31)"><circle cx="17" cy="19" r="3.6"/><path fill="none" stroke="#fff8df" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" d="M10.5 15.5L17 26L23.5 15.5M17 26V38M17 38L12.5 46M17 38L21.5 46"/><circle cx="43" cy="19" r="3.6"/><path fill="none" stroke="#fff8df" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" d="M36.5 15.5L43 26L49.5 15.5M43 26V38M43 38L38.5 46M43 38L47.5 46"/><circle cx="30" cy="15" r="3.6"/><path fill="none" stroke="#fff8df" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" d="M23.5 11.5L30 22L36.5 11.5M30 22V34M30 34L25.5 42M30 34L34.5 42"/></g></g></svg>`,puskas:`<svg class="award-crest" viewBox="0 0 60 66" aria-hidden="true" focusable="false"><path fill="#b8433b" d="M4 3h52v35c0 13-15 21-26 26C19 59 4 51 4 38z"/><path fill="none" stroke="#ffffff66" stroke-width="2" d="M9 8h42v29c0 10-11 17-21 22C20 54 9 47 9 37z"/><g fill="#fff8df"><g transform="translate(30 31) scale(.75) translate(-30 -31)"><path fill="none" stroke="#fff8df" stroke-width="3.2" stroke-linecap="round" stroke-dasharray="0.1 6" d="M13 46C16 24 26 17 37 19"/><circle cx="40" cy="22" r="8.5"/><path fill="#b8433b" d="M40 17.2l4 3-1.5 4.6h-5L36 20.2z"/><path fill="none" stroke="#fff8df" stroke-width="3" stroke-linecap="round" d="M43 11l3-4M49 16l4-2M50 25l4 1"/></g></g></svg>`,glove:`<svg class="award-crest" viewBox="0 0 60 66" aria-hidden="true" focusable="false"><path fill="#245f7a" d="M4 3h52v35c0 13-15 21-26 26C19 59 4 51 4 38z"/><path fill="none" stroke="#ffffff66" stroke-width="2" d="M9 8h42v29c0 10-11 17-21 22C20 54 9 47 9 37z"/><g fill="#fff8df"><g transform="translate(30 31) scale(.75) translate(-30 -31)"><rect x="16" y="13" width="6.4" height="19" rx="3.2"/><rect x="23.4" y="9.5" width="6.4" height="22.5" rx="3.2"/><rect x="30.8" y="10.5" width="6.4" height="21.5" rx="3.2"/><rect x="38.2" y="14.5" width="6.4" height="17.5" rx="3.2"/><rect x="9" y="27" width="6.4" height="14" rx="3.2" transform="rotate(-28 12 34)"/><path d="M16 28h28.6v9c0 7-5 10.5-11 10.5h-6.6c-6.2 0-11-3.5-11-10.5z"/><rect x="19.5" y="46.5" width="21.5" height="6.5" rx="2"/></g></g></svg>`};
function awardCrest(key){return AWARD_CRESTS[key]||''}
// Hengelås-skjold (samme stil som lag- og premieskjoldene) for låst sluttspill.
function lockCrest(cls='lock-crest'){return `<svg class="${cls}" viewBox="0 0 60 66" aria-hidden="true" focusable="false"><path fill="#5d7f74" d="M4 3h52v35c0 13-15 21-26 26C19 59 4 51 4 38z"/><path fill="none" stroke="#ffffff66" stroke-width="2" d="M9 8h42v29c0 10-11 17-21 22C20 54 9 47 9 37z"/><g fill="#fff8df"><rect x="17" y="27" width="26" height="19" rx="3.5"/><path fill="none" stroke="#fff8df" stroke-width="4" stroke-linecap="round" d="M22.5 27v-5.5a7.5 7.5 0 0 1 15 0V27"/></g><g fill="#5d7f74"><circle cx="30" cy="35.5" r="3"/><rect x="28.6" y="36" width="2.8" height="6.5" rx="1.2"/></g></svg>`}

